-- PT112-S3-Q6. Batch 13.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch13$PT112-S3-Q6$batch13$ AND q.stimulus=$batch13$Government official: A satisfactory way of eliminating chronic food shortages in our country is not easily achievable. Direct aid from other countries in the form of food shipments tends to undermine our prospects for long-term agricultural self-sufficiency. If external sources of food are delivered effectively by external institutions, local food producers and suppliers are forced out of business. On the other hand, foreign capital funneled to long-term development projects would inject so much cash into our economy that inflation would drive the price of food beyond the reach of most of our citizens.$batch13$ AND q.prompt=$batch13$The claim that foreign capital funneled into the economy would cause inflation plays which one of the following roles in the government official's argument?$batch13$ AND q.correct_choice=$batch13$B$batch13$) THEN RAISE EXCEPTION 'Question changed: PT112-S3-Q6'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch13$PT112-S3-Q6$batch13$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT112-S3-Q6'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch13$PT112-S3-Q6$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch13$Conclusion$batch13$, $batch13$There is no easy way to end the country's chronic food shortages.$batch13$), (1, $batch13$Evidence$batch13$, $batch13$Direct food aid would undermine long-term self-sufficiency, because effective food deliveries force local producers and suppliers out of business. Foreign capital for long-term development would cause inflation that prices food out of reach for most citizens.$batch13$), (2, $batch13$Evaluate$batch13$, $batch13$The official walks through two options and shows a problem with each. Food aid hurts local farming. Foreign capital causes inflation. If both options backfire, no solution is easy. So the inflation claim is one of the two reasons for the first sentence.$batch13$), (3, $batch13$Goal$batch13$, $batch13$The inflation claim supports the conclusion that there's no easy solution.$batch13$)) v(position,label,body) WHERE q.qid=$batch13$PT112-S3-Q6$batch13$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch13$A$batch13$, $batch13$The official never argues the country must someday be self-sufficient, and the inflation claim is about foreign capital, not self-sufficiency.$batch13$), ($batch13$B$batch13$, $batch13$The inflation problem knocks out the second option, which supports the claim that no easy solution exists.$batch13$), ($batch13$C$batch13$, $batch13$Nothing supports the inflation claim, and the argument never makes the self-sufficiency claim.$batch13$), ($batch13$D$batch13$, $batch13$This is the most tempting wrong answer. The inflation claim is about foreign capital. The problem with food donations is a separate premise.$batch13$), ($batch13$E$batch13$, $batch13$The two problems sit side by side, one for each option. The claim about producers going out of business doesn't support the inflation claim.$batch13$)) v(letter,body) WHERE q.qid=$batch13$PT112-S3-Q6$batch13$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
